def _clip_file_size(item: Any) -> Tuple[Optional[str], Optional[int]]:
    """(file_path, size_bytes) for a MediaPoolItem, or (path|None, None)."""
    try:
        path = item.GetClipProperty("File Path")
        if isinstance(path, str) and path and os.path.exists(path):
            return path, os.path.getsize(path)
        return (path if isinstance(path, str) and path else None), None
    except Exception:
        return None, None

def _timeline_fps(tl):
    try:
        setting = tl.GetSetting("timelineFrameRate")
    except Exception as exc:
        return None, _err(f"Failed to read timelineFrameRate: {exc}")
    match = re.search(r"\d+(?:\.\d+)?", str(setting or ""))
    if not match:
        return None, _err("Could not determine timeline frame rate")
    return float(match.group(0)), None

def _timecode_to_frame_id(timecode, fps):
    if not isinstance(timecode, str):
        return None, _err("timecode must be a string like '01:00:00:00'")
    tc = timecode.strip()
    drop_frame = ";" in tc
    parts = tc.replace(";", ":").replace(".", ":").split(":")
    if len(parts) != 4:
        return None, _err("timecode must use HH:MM:SS:FF format")
    try:
        hours, minutes, seconds, frames = [int(part) for part in parts]
    except ValueError:
        return None, _err("timecode fields must be numeric")

    nominal_fps = int(round(float(fps)))
    if nominal_fps <= 0:
        return None, _err("timeline frame rate must be greater than zero")
    if hours < 0 or minutes < 0 or minutes > 59 or seconds < 0 or seconds > 59:
        return None, _err("timecode hours must be non-negative, and minutes/seconds must be between 0 and 59")
    if frames < 0 or frames >= nominal_fps:
        return None, _err(f"timecode frame component must be between 0 and {nominal_fps - 1}")

    total_frames = ((hours * 3600 + minutes * 60 + seconds) * nominal_fps) + frames
    if drop_frame:
        drop_frames = int(round(nominal_fps * 0.0666666667))
        total_minutes = hours * 60 + minutes
        total_frames -= drop_frames * (total_minutes - total_minutes // 10)
    return total_frames, None

def _timeline_timecode_to_frame_id(tl, timecode):
    if tl is None:
        return None, _err("timecode markers require a timeline")
    fps, err = _timeline_fps(tl)
    if err:
        return None, err
    return _timecode_to_frame_id(timecode, fps)

def _frame_id_to_timecode(frame: int, fps: float, separator: str = ":") -> str:
    nominal_fps = max(1, int(round(float(fps))))
    frame = max(0, int(frame))
    total_seconds, frames = divmod(frame, nominal_fps)
    hours, rem = divmod(total_seconds, 3600)
    minutes, seconds = divmod(rem, 60)
    return f"{hours:02d}:{minutes:02d}:{seconds:02d}{separator}{frames:02d}"

def _timeline_frame_id_to_timecode(tl, frame: int) -> Tuple[Optional[str], Optional[Dict[str, Any]]]:
    fps, err = _timeline_fps(tl)
    if err:
        return None, err
    return _frame_id_to_timecode(int(frame), fps), None

def _current_timeline_frame_id(tl):
    """Absolute frame at the playhead, matching TimelineItem.GetStart()."""
    if tl is None:
        return None, _err("current playhead marker requires a timeline")
    try:
        timecode = tl.GetCurrentTimecode()
    except Exception as exc:
        return None, _err(f"Failed to read current timeline timecode: {exc}")
    if not timecode:
        return None, _err("Current timeline timecode is unavailable")
    return _timeline_timecode_to_frame_id(tl, timecode)

def _get_mp():
    pm, proj, err = _check()
    if err:
        return None, None, None, err
    mp = proj.GetMediaPool()
    if not mp:
        return pm, proj, None, _err(
            "Failed to get MediaPool",
            code="NO_MEDIA_POOL", category="resolve_api_failed",
        )
    return pm, proj, mp, None

def _get_tl():
    pm, proj, err = _check()
    if err:
        return None, None, err
    tl = proj.GetCurrentTimeline()
    if not tl:
        return proj, None, _err(
            "No current timeline",
            code="NO_CURRENT_TIMELINE", category="precondition",
            remediation="Open a timeline via timeline(action='set_current', params={'index': N}) or in the Resolve UI.",
        )
    return proj, tl, None

def _get_item(p):
    proj, tl, err = _get_tl()
    if err:
        return None, None, err
    track_type = p.get("track_type", "video")
    track_index = p.get("track_index", 1)
    item_index = p.get("item_index", 0)
    items = tl.GetItemListInTrack(track_type, track_index)
    # Reject negatives explicitly: Python's reverse-indexing would otherwise
    # silently return the wrong item for item_index < 0 (EX5).
    if not items or not isinstance(item_index, int) or item_index < 0 or item_index >= len(items):
        return tl, None, _err(
            f"No item at index {item_index} on {track_type} track {track_index}",
            code="ITEM_INDEX_OUT_OF_RANGE", category="invalid_input",
            remediation="Call timeline(action='get_items', params={'track_type': ..., 'index': ...}) to list valid items.",
        )
    return tl, items[item_index], None

def _find_clip(folder, clip_id):
    for clip in (folder.GetClipList() or []):
        if clip.GetUniqueId() == clip_id:
            return clip
    for sub in (folder.GetSubFolderList() or []):
        found = _find_clip(sub, clip_id)
        if found:
            return found
    return None

def _find_clip_with_parent(folder, clip_id, _parent=None):
    """Return (clip, parent_folder) for clip_id, searching recursively.

    `parent_folder` is the immediate folder containing the clip, which is what
    MediaPool.SetCurrentFolder() needs in order to reveal the clip in the bin.
    Returns (None, None) if not found.
    """
    for clip in (folder.GetClipList() or []):
        if clip.GetUniqueId() == clip_id:
            return clip, folder
    for sub in (folder.GetSubFolderList() or []):
        found_clip, found_parent = _find_clip_with_parent(sub, clip_id, folder)
        if found_clip:
            return found_clip, found_parent
    return None, None

def _project_summary(proj, *, include_clips=False, clip_limit=50):
    """Live structural readout of a project: page, timelines, media-pool inventory.

    Distinct from the analysis-derived bin summary — this is a cheap "what's in
    this project right now" snapshot that needs no prior analysis.
    """
    by_type: Dict[str, int] = {}
    sample_clips: List[Dict[str, Any]] = []
    folder_count = 0
    clip_count = 0

    mp = proj.GetMediaPool()
    root = mp.GetRootFolder() if mp else None

    def walk(folder):
        nonlocal folder_count, clip_count
        folder_count += 1
        for clip in (folder.GetClipList() or []):
            clip_count += 1
            try:
                ctype = clip.GetClipProperty("Type") or "Unknown"
            except Exception:
                ctype = "Unknown"
            by_type[ctype] = by_type.get(ctype, 0) + 1
            if include_clips and len(sample_clips) < clip_limit:
                sample_clips.append({
                    "name": _clip_name(clip),
                    "type": ctype,
                    "id": clip.GetUniqueId(),
                })
        for sub in (folder.GetSubFolderList() or []):
            walk(sub)

    if root:
        walk(root)

    cur_tl = proj.GetCurrentTimeline()
    r = get_resolve()
    return {
        "project": proj.GetName(),
        "current_page": r.GetCurrentPage() if r else None,
        "timeline_count": proj.GetTimelineCount(),
        "current_timeline": cur_tl.GetName() if cur_tl else None,
        "media_pool": {
            "folder_count": folder_count,
            "clip_count": clip_count,
            "by_type": by_type,
        },
        "clips": sample_clips if include_clips else None,
    }

