def timeline_frame_duration(tl, start=None, end=None):
    """Timeline duration in frames, or None.

    ONE definition, because the repo had three: `end - start` in
    core/brain_edits.py and `end - start + 1` in both granular/timeline.py and
    project_lifecycle/utils/project_properties.py. At most one could be right;
    the others reported a duration off by one frame (#141 finding 6).

    `Timeline.GetEndFrame()` is EXCLUSIVE — one past the last frame, the same
    convention as `TimelineItem.GetEnd()`. Measured live on Resolve Studio
    21.0.2.4 (2026-07-28) with `tests/live_timeline_end_frame_probe.py
    --allow-mutation`, against synthesised clips of known length: a 48-frame
    clip gives GetStartFrame()=86400, GetEndFrame()=86448, and a 100-frame clip
    gives 86400/86500. So `end - start` is the duration and the `+ 1` was wrong.

    That means the MAJORITY convention was the broken one: `granular/timeline.py`
    and `project_lifecycle/utils/project_properties.py` both reported one frame
    too many, and `core/brain_edits.py` was the single site that had it right.
    Recorded in src/core/api_truth.py.
    """
    if start is None:
        start = _frame_int(tl.GetStartFrame())
    if end is None:
        end = _frame_int(tl.GetEndFrame())
    if start is None or end is None:
        return None
    return max(0, end - start)

def _timeline_item_track_info(item):
    try:
        track_info = item.GetTrackTypeAndIndex()
    except Exception as exc:
        return None, _err(f"GetTrackTypeAndIndex: {exc}")
    if not track_info or len(track_info) < 2:
        return None, _err("GetTrackTypeAndIndex returned empty")
    try:
        return (str(track_info[0]).lower(), int(track_info[1])), None
    except (TypeError, ValueError):
        return None, _err("invalid source track index")

def _timeline_item_summary(item, track_info=None):
    if not item:
        return None
    start = end = duration = source_start = source_end = None
    try:
        start = _frame_int(item.GetStart())
        end = _frame_int(item.GetEnd())
    except Exception as exc:
        logger.debug("GetStart/GetEnd failed in item summary: %s", exc)
    duration = _timeline_item_duration(item, start, end)
    source_start = _timeline_item_source_start(item)
    if source_start is not None and duration is not None:
        source_end = source_start + duration
    if track_info is None:
        track_info, _ = _timeline_item_track_info(item)
    media_pool_item = _timeline_item_media_pool_item(item)
    summary = {
        "timeline_item_id": _safe_timeline_item_id(item),
        "name": _safe_timeline_item_name(item),
        "track_type": track_info[0] if track_info else None,
        "track_index": track_info[1] if track_info else None,
        "start": start,
        "end": end,
        "duration": duration,
        "source_start": source_start,
        "source_end": source_end,
        "media_pool_item_id": _safe_media_pool_item_id(media_pool_item),
        "media_pool_item_name": _safe_media_pool_item_name(media_pool_item),
    }
    return summary

def _track_items_sorted(tl, track_type: str, track_index: int):
    try:
        items = tl.GetItemListInTrack(track_type, track_index) or []
    except Exception:
        return []

    sortable = []
    for item in items:
        try:
            start = _frame_int(item.GetStart())
            end = _frame_int(item.GetEnd())
        except Exception as exc:
            logger.debug("GetStart/GetEnd failed — item dropped from sorted track list: %s", exc)
            continue
        if start is None or end is None:
            continue
        sortable.append((start, end, item))
    sortable.sort(key=lambda row: (row[0], row[1]))
    return sortable

def _coerce_item_list(value):
    if value is None:
        return []
    if isinstance(value, dict):
        iterable = value.values()
    elif isinstance(value, (list, tuple, set)):
        iterable = value
    else:
        iterable = [value]
    return [item for item in iterable if item]

def _get_selected_timeline_items(tl):
    warnings = []
    for method_name in ("GetSelectedTimelineItems", "GetSelectedItems", "GetSelectedClips"):
        method = getattr(tl, method_name, None)
        if not callable(method):
            continue
        try:
            items = _coerce_item_list(method())
        except Exception as exc:
            warnings.append(f"{method_name} failed: {exc}")
            continue
        if items:
            return items, warnings

    current_video = getattr(tl, "GetCurrentVideoItem", None)
    if callable(current_video):
        try:
            item = current_video()
        except Exception as exc:
            return [], warnings + [f"GetCurrentVideoItem failed: {exc}"]
        if item:
            return [item], warnings + [
                "Timeline selection API is unavailable; used current video item as selected source"
            ]
    return [], warnings

def _track_selector(p: Dict[str, Any]):
    """(track_type, track_index, err) from a params dict.

    Accepts the 1-based track index as either ``index`` or ``track_index``. err
    is a validation message (None on success) so a missing or malformed selector
    returns a structured error.
    """
    normalized = dict(p)
    if normalized.get("index") is None and normalized.get("track_index") is not None:
        normalized["index"] = normalized["track_index"]
    err, clean = _validate_params(normalized, {
        "track_type": {"type": str, "required": True, "enum": ["video", "audio", "subtitle"]},
        "index": {"type": int, "required": True, "min": 1},
    })
    if err:
        if err.startswith("'index' is required"):
            err = "requires a 1-based track index ('index' or 'track_index')"
        return None, None, err
    return clean["track_type"], clean["index"], None

