def _timeline_item_ids(items):
    ids = []
    for item in items:
        item_id = _safe_timeline_item_id(item)
        if item_id:
            ids.append(item_id)
    return ids

def _collect_timeline_items_in_range(tl, p: Dict[str, Any]):
    start, end, err = _range_frames_from_params(tl, p)
    if err:
        return None, None, None, err
    items = []
    for track_type in _range_track_types(p):
        if track_type not in {"video", "audio"}:
            return None, None, None, _err(f"Range actions support video/audio tracks, got {track_type!r}")
        indices, indices_err = _range_track_indices(p, track_type)
        if indices_err:
            return None, None, None, indices_err
        if indices is None:
            indices = list(range(1, _timeline_track_count(tl, track_type) + 1))
        for track_index in indices:
            for item in (tl.GetItemListInTrack(track_type, track_index) or []):
                item_start = _frame_int(item.GetStart())
                item_end = _frame_int(item.GetEnd())
                if item_start is None or item_end is None:
                    continue
                if item_start < end and item_end > start:
                    items.append((track_type, track_index, item, max(item_start, start), min(item_end, end)))
    return start, end, items, None

def _timeline_item_probe(item):
    known_property_keys = []
    for keys in _DUPLICATE_COPY_PROPERTY_KEYS.values():
        for key in keys:
            if key not in known_property_keys:
                known_property_keys.append(key)

    all_properties, all_properties_error = _safe_get_property(item)
    known_properties = {}
    for key in known_property_keys:
        value, err = _safe_get_property(item, key)
        known_properties[key] = {"value": value, "error": err} if err else {"value": value}

    linked = []
    get_linked = getattr(item, "GetLinkedItems", None)
    if callable(get_linked):
        try:
            linked = [_timeline_item_summary(linked_item) for linked_item in (get_linked() or [])]
        except Exception as exc:
            linked = [{"error": str(exc)}]

    method_names = [
        "GetMediaPoolItem",
        "GetLinkedItems",
        "GetProperty",
        "SetProperty",
        "GetKeyframeCount",
        "GetKeyframeAtIndex",
        "GetPropertyAtKeyframeIndex",
        "AddKeyframe",
        "SetKeyframeInterpolation",
        "GetFusionCompCount",
        "ExportFusionComp",
        "ImportFusionComp",
        "CopyGrades",
        "GetTakesCount",
        "AddTake",
        "GetVoiceIsolationState",
        "SetVoiceIsolationState",
        "GetClipColor",
        "SetClipColor",
    ]

    return {
        "summary": _timeline_item_summary(item),
        "methods": _callable_method_names(item, method_names),
        "all_properties": all_properties,
        "all_properties_error": all_properties_error,
        "known_properties": known_properties,
        "keyframes": _probe_keyframes(item, known_property_keys),
        "linked_items": linked,
    }

def _timeline_by_selector(proj, p: Dict[str, Any], *, prefix: str):
    timeline_id = p.get(f"{prefix}_timeline_id") or p.get(f"{prefix}_id")
    timeline_index = p.get(f"{prefix}_timeline_index") or p.get(f"{prefix}_index")
    if timeline_id:
        want = str(timeline_id)
        for index in range(1, int(proj.GetTimelineCount() or 0) + 1):
            tl = proj.GetTimelineByIndex(index)
            if tl and str(tl.GetUniqueId()) == want:
                return tl, None
        return None, _err(f"{prefix} timeline not found: {timeline_id}")
    if timeline_index is not None:
        try:
            index = int(timeline_index)
        except (TypeError, ValueError):
            return None, _err(f"{prefix}_timeline_index must be an integer")
        tl = proj.GetTimelineByIndex(index)
        return (tl, None) if tl else (None, _err(f"No {prefix} timeline at index {index}"))
    return proj.GetCurrentTimeline(), None

def _find_timeline_by_name(proj, name: Any):
    want = str(name or "")
    for index in range(1, int(proj.GetTimelineCount() or 0) + 1):
        tl = proj.GetTimelineByIndex(index)
        if tl and str(tl.GetName()) == want:
            return tl, index
    return None, None

def _find_timeline_by_id(proj, timeline_id: Any):
    want = str(timeline_id or "")
    for index in range(1, int(proj.GetTimelineCount() or 0) + 1):
        tl = proj.GetTimelineByIndex(index)
        if tl and str(tl.GetUniqueId()) == want:
            return tl, index
    return None, None


def _set_current_timeline(proj, tl) -> bool:
    """Make `tl` current, verified by reading the current timeline back.

    #113 Tier 1. Resolve targets the CURRENT timeline implicitly in several
    APIs (`AppendToTimeline` has no target argument, render jobs bind to
    whatever is current), so a switch that silently fails sends the next
    mutation to the WRONG timeline. `timeline_edit._timeline_insert_edit_impl`
    documents that exact bug being found live — "the clip silently appended
    onto the original, colliding with content the ripple never touched there".
    Every one of those call sites discarded `SetCurrentTimeline`'s return.

    Verification is by read-back rather than by trusting the return value,
    which is the defense `src/core/readback.py` exists for: Resolve setters
    return values that "do not reflect what actually happened". Read-back also
    keeps this change safe — a build that returns a falsy value on a switch
    that *did* take effect still reports True here, so turning these sites into
    hard failures cannot break a working flow.

    Returns True when the current timeline is `tl` afterwards, False otherwise.
    Never raises.
    """
    if proj is None or tl is None:
        return False

    reported = None
    try:
        reported = proj.SetCurrentTimeline(tl)
    except Exception:
        logger.debug("SetCurrentTimeline raised", exc_info=True)
        # Fall through — the read-back below is the authority either way.

    try:
        want = str(tl.GetUniqueId())
    except Exception:
        # No id to compare against; the reported value is all we have.
        return bool(reported)

    try:
        current = proj.GetCurrentTimeline()
        if current is not None and str(current.GetUniqueId()) == want:
            return True
    except Exception:
        logger.debug("GetCurrentTimeline read-back failed", exc_info=True)
        return bool(reported)

    return False


def _normalize_timecode(value: Any) -> Optional[str]:
    """Canonicalize an HH:MM:SS:FF timecode for comparison.

    Zero-pads each field and normalizes the frame separator, so a drop-frame
    timeline reporting `01:00:00;00` compares equal to a requested
    `01:00:00:00`, and `1:00:00:00` equals `01:00:00:00`. Returns None when the
    value isn't timecode-shaped, which callers treat as "cannot verify".
    """
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    parts = re.split(r"[:;.]", text)
    if len(parts) != 4 or not all(part.isdigit() for part in parts):
        return None
    return ":".join(part.zfill(2) for part in parts)


def _set_start_timecode(tl, timecode: Any) -> bool:
    """Set a timeline's start timecode, verified by reading it back.

    #113 Tier 2, and the same class as #111 finding 5 (`ensure_timeline`
    discarding the `timelineFrameRate` set): callers compute ABSOLUTE record
    frames from the requested start, then `AppendToTimeline` places clips at
    those frames. If the timecode silently fails to take, every clip lands at
    the wrong offset — a conform/delivery tool mis-timing its whole output while
    reporting success. All three call sites wrapped this in
    `try: ... except: pass` and discarded the return.

    Verified by read-back rather than by the return value, per
    `src/core/readback.py`. Comparison is normalized, so a drop-frame timeline
    reporting `01:00:00;00` for a requested `01:00:00:00` is not a false
    failure. Returns True when the start timecode reads back as requested.
    Never raises.
    """
    if tl is None:
        return False

    reported = None
    try:
        reported = tl.SetStartTimecode(str(timecode))
    except Exception:
        logger.debug("SetStartTimecode raised", exc_info=True)

    want = _normalize_timecode(timecode)
    if want is None:
        # Not timecode-shaped — nothing meaningful to compare against.
        return bool(reported)

    try:
        got = _normalize_timecode(tl.GetStartTimecode())
    except Exception:
        logger.debug("GetStartTimecode read-back failed", exc_info=True)
        return bool(reported)

    if got is None:
        return bool(reported)
    return got == want


def _clip_name(clip):
    try:
        return clip.GetName()
    except Exception:
        return None

def _project_name_and_id(project) -> Tuple[Optional[str], Optional[str]]:
    name = project_id = None
    if project and _has_method(project, "GetName"):
        try:
            name = project.GetName()
        except Exception:
            name = None
    if project and _has_method(project, "GetUniqueId"):
        try:
            project_id = project.GetUniqueId()
        except Exception:
            project_id = None
    return name, project_id

def _metadata_write_field_for_field(field: str) -> str:
    return _METADATA_FIELD_WRITE_ALIASES.get(field, field)

def _clips_from_params(root, mp, p: Dict[str, Any], *, key: str = "clip_ids"):
    ids = p.get(key) or p.get("ids")
    selected = bool(p.get("selected", False))
    clips = []
    missing = []
    if ids:
        if not isinstance(ids, list):
            return None, _err(f"{key} must be a list")
        for clip_id in ids:
            clip = _find_clip(root, str(clip_id))
            if clip:
                clips.append(clip)
            else:
                missing.append(str(clip_id))
    if selected:
        clips.extend(mp.GetSelectedClips() or [])
    deduped = []
    seen = set()
    for clip in clips:
        clip_id = _safe_media_pool_item_id(clip) or id(clip)
        if clip_id in seen:
            continue
        seen.add(clip_id)
        deduped.append(clip)
    if not deduped:
        return None, _err(f"Provide {key} or selected=True")
    return (deduped, missing), None

def _clip_summaries(clips):
    return [_media_pool_item_summary(clip) for clip in clips]


def _range_frames_from_params(tl, p: Dict[str, Any]):
    if p.get("use_mark_in_out", p.get("useMarkInOut", False)):
        mark = tl.GetMarkInOut() or {}
        if not isinstance(mark, dict):
            return None, None, _err(
                f"GetMarkInOut returned {type(mark).__name__}, expected a dict of "
                "{'video'|'audio': {'in': int, 'out': int}}")
        mark_type = p.get("mark_type", p.get("markType", "video"))
        if mark_type not in mark:
            mark_type = "video" if "video" in mark else "audio" if "audio" in mark else None
        if not mark_type:
            return None, None, _err("No timeline mark in/out is set")
        # Shape check before .get(): the dict-of-dicts layout was assumed with
        # no verification, so an unexpected payload raised AttributeError out of
        # the tool (#142 finding 4).
        marks = mark.get(mark_type)
        if not isinstance(marks, dict):
            return None, None, _err(
                f"GetMarkInOut()[{mark_type!r}] is {type(marks).__name__}, expected "
                "a dict with 'in' and 'out'")
        start = _frame_int(marks.get("in"))
        end = _frame_int(marks.get("out"))
        if start is None or end is None:
            return None, None, _err(
                f"GetMarkInOut()[{mark_type!r}] has no numeric 'in'/'out'")
        return start, end, None
    start = p.get("start_frame", p.get("startFrame"))
    end = p.get("end_frame", p.get("endFrame"))
    if start is None or end is None:
        return None, None, _err("Range actions require start_frame/end_frame or use_mark_in_out=True")
    start = _frame_int(start)
    end = _frame_int(end)
    if start is None or end is None:
        return None, None, _err("start_frame and end_frame must be numeric")
    if end <= start:
        return None, None, _err("end_frame must be greater than start_frame")
    return start, end, None


def _range_track_types(p: Dict[str, Any]):
    raw = p.get("track_types", p.get("trackTypes", p.get("track_type", p.get("trackType", "video"))))
    if raw == "all":
        return ["video", "audio"]
    if isinstance(raw, str):
        return [part.strip().lower() for part in raw.split(",") if part.strip()]
    if isinstance(raw, list):
        return [str(part).strip().lower() for part in raw if str(part).strip()]
    return ["video"]


def _range_track_indices(p: Dict[str, Any], track_type: str):
    """Parse the caller's track-index selector. Returns ``(indices, err)``.

    ``indices`` is None when the caller didn't specify any (meaning "all
    tracks"); ``err`` is an error envelope when what they did specify cannot be
    read as track indices.

    This used to be a bare comprehension over ``int(...)``, so ordinary caller
    input escaped as a raw traceback (#142 finding 4): ``track_indices="V1"``
    raised ValueError, and ``track_indices=2.0`` raised "TypeError: 'float'
    object is not iterable". It sits on the path of every copy_range /
    duplicate_range / overwrite_range / lift_range via
    _collect_timeline_items_in_range.
    """
    key = f"{track_type}_track_indices"
    raw = p.get(key, p.get(f"{track_type}TrackIndices", p.get("track_indices", p.get("trackIndices"))))
    if raw is None:
        return None, None
    # bool is an int subclass, and track 'True' is not a thing.
    if isinstance(raw, bool):
        return None, _err(f"{key} must be a track index or a list of them, got {raw!r}",
                          code="INVALID_TRACK_INDICES", category="invalid_input")
    if isinstance(raw, int):
        parts = [raw]
    elif isinstance(raw, float):
        # A whole-number float is an obvious "2.0 meant track 2"; anything else
        # is a mistake worth naming rather than truncating.
        parts = [raw]
    elif isinstance(raw, str):
        parts = [part.strip() for part in raw.split(",") if part.strip()]
    elif isinstance(raw, (list, tuple)):
        parts = list(raw)
    else:
        return None, _err(
            f"{key} must be a track index, a comma-separated string, or a list; "
            f"got {type(raw).__name__}",
            code="INVALID_TRACK_INDICES", category="invalid_input")

    indices = []
    for part in parts:
        index = _frame_int(part)
        if index is None:
            return None, _err(
                f"{key} entry {part!r} is not a track index. Use numbers "
                "(1, \"1,2\", [1, 2]), not track names like \"V1\".",
                code="INVALID_TRACK_INDICES", category="invalid_input")
        if index < 1:
            return None, _err(
                f"{key} entry {part!r} is out of range — Resolve track indices start at 1.",
                code="INVALID_TRACK_INDICES", category="invalid_input")
        indices.append(index)
    if not indices:
        return None, None
    return indices, None


def _safe_media_pool_item_id(mpi):
    try:
        get_unique_id = getattr(mpi, "GetUniqueId", None)
        if callable(get_unique_id):
            media_id = get_unique_id()
            return None if media_id in (None, "") else str(media_id)
    except Exception:
        return None
    return None


def _safe_media_pool_item_name(mpi):
    try:
        get_name = getattr(mpi, "GetName", None)
        if callable(get_name):
            name = get_name()
            return None if name is None else str(name)
    except Exception:
        return None
    return None


def _media_pool_item_summary(clip):
    if not clip:
        return None
    summary = {
        "name": _safe_media_pool_item_name(clip),
        "id": _safe_media_pool_item_id(clip),
        "media_id": None,
        "file_path": None,
        "type": None,
        "duration": None,
    }
    media_id, _ = _safe_clip_call(clip, "GetMediaId")
    if media_id is not None:
        summary["media_id"] = media_id
    properties, _ = _safe_clip_call(clip, "GetClipProperty", "")
    if isinstance(properties, dict):
        summary["file_path"] = properties.get("File Path") or properties.get("FilePath")
        summary["type"] = properties.get("Type")
        summary["duration"] = properties.get("Duration")
    return summary


def _probe_keyframes(item, properties: List[str]):
    out = {}
    for prop in properties:
        try:
            count = int(item.GetKeyframeCount(prop) or 0)
        except Exception as exc:
            out[prop] = {"available": False, "error": str(exc)}
            continue
        frames = []
        for index in range(count):
            try:
                keyframe = item.GetKeyframeAtIndex(prop, index)
                value = item.GetPropertyAtKeyframeIndex(prop, index)
                frames.append({"keyframe": _ser(keyframe), "value": _ser(value)})
            except Exception as exc:
                frames.append({"error": str(exc)})
        out[prop] = {"available": True, "count": count, "frames": frames}
    return out


